 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider lines are overwhelmingly one color (typically 8 or 9); some
    # divider intersections are replaced by marker colors.
    def line_color_counts(values):
        return Counter(values).most_common(1)[0]
    row_lines = []
    for r, row in enumerate(grid):
        color, n = line_color_counts(row)
        if n >= 0.75 * w:
            row_lines.append((r, color))
    col_lines = []
    for c in range(w):
        color, n = line_color_counts([grid[r][c] for r in range(h)])
        if n >= 0.60 * h:
            col_lines.append((c, color))
    rows = [r for r, _ in row_lines]
    cols = [c for c, _ in col_lines]
    if len(rows) < 2 or len(cols) < 2:
        raise ValueError('divider lattice not found')
    divider_colors = {v for _, v in row_lines + col_lines}
    # Infer ordinary panel/background color from non-divider cells.
    interior = [grid[r][c] for r in range(h) for c in range(w)
                if r not in rows and c not in cols]
    bg = Counter(interior).most_common(1)[0][0]
    out = []
    for ra, rb in zip(rows, rows[1:]):
        outrow = []
        for ca, cb in zip(cols, cols[1:]):
            corners = [grid[ra][ca], grid[ra][cb], grid[rb][ca], grid[rb][cb]]
            v = corners[0]
            if v not in divider_colors and v != bg and all(x == v for x in corners):
                outrow.append(v)
            else:
                outrow.append(bg)
        out.append(outrow)
    return out

