 "content": "from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    # Detect highly uniform divider rows and columns, allowing marker cells.
    rs=[]
    for r,row in enumerate(grid):
        color,n=Counter(row).most_common(1)[0]
        if n >= w-2: rs.append((r,color))
    cs=[]
    for c in range(w):
        color,n=Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if n >= h-2: cs.append((c,color))
    rows=[r for r,_ in rs]; cols=[c for c,_ in cs]
    # Output summarizes marker colors at the intersections of parallel dividers.
    # Use the dominant ordinary grid color as the default cell value.
    divcolors={x for _,x in rs+cs}
    normal=[grid[r][c] for r in range(h) for c in range(w) if grid[r][c] not in divcolors]
    default=Counter(normal).most_common(1)[0][0]
    ans=[]
    for r1,r2 in zip(rows,rows[1:]):
        line=[]
        for c1,c2 in zip(cols,cols[1:]):
            corners=(grid[r1][c1],grid[r1][c2],grid[r2][c1],grid[r2][c2])
            value=corners[0]
            line.append(value if value not in divcolors and all(x==value for x in corners) else default)
        ans.append(line)
    return ans

if __name__ == '__main__':
    pass
